def gpx_fields_to_xml(instance: Any, tag: str, version: str,
    custom_attributes: Dict[str, str]={}, nsmap: Dict[str, str]={},
    prettyprint: bool=True, indent: str='', empty_body: bool=False) ->str:
    if not prettyprint:
        indent = ''
    fields = instance.gpx_10_fields
    if version == '1.1':
        fields = instance.gpx_11_fields

    body = []
    attributes = []

    node_path = []
    open_nodes = []

    for gpx_field in fields:
        if isinstance(gpx_field, str):
            gpx_field_tag = gpx_field.partition(':')[0]
            if gpx_field_tag.startswith('/'):
                tag_name = gpx_field_tag[1:]
                if open_nodes and open_nodes[-1][0] == tag_name:
                    node_indent, node_tag, node_body = open_nodes[-1]
                    open_nodes.pop()
                    if node_body:
                        chunk = f'\n{node_indent}<{node_tag}>{"".join(node_body)}\n{node_indent}</{node_tag}>'
                    else:
                        chunk = ''
                    if open_nodes:
                        open_nodes[-1][2].append(chunk)
                    else:
                        body.append(chunk)
                if node_path:
                    node_path.pop()
            else:
                node_path.append(gpx_field_tag)
                current_indent = indent + '  ' * len(node_path)
                open_nodes.append([current_indent, gpx_field_tag, []])
        else:
            value = getattr(instance, gpx_field.name)
            if gpx_field.attribute:
                xml_value = gpx_field.to_xml(value, version, nsmap, prettyprint=prettyprint, indent=indent + '  ')
                if xml_value:
                    attributes.append(xml_value)
            else:
                current_indent = indent + '  ' * (len(node_path) + 1)
                xml_value = gpx_field.to_xml(value, version, nsmap, prettyprint=prettyprint, indent=current_indent)
                if xml_value:
                    if open_nodes:
                        open_nodes[-1][2].append(xml_value)
                    else:
                        body.append(xml_value)

    for attr_name, attr_value in custom_attributes.items():
        attributes.append(f'{attr_name}="{attr_value}"')

    if tag is None:
        return ''.join(body)

    result = []
    if prettyprint:
        result.append(f'\n{indent}')
    result.append(f'<{tag}')
    for attr in attributes:
        result.append(f' {attr}')
    if body or empty_body:
        result.append('>')
        result.append(''.join(body))
        if prettyprint and body and not all(b.strip() == '' for b in body):
            result.append(f'\n{indent}')
        result.append(f'</{tag}>')
    else:
        result.append(' />')

    return ''.join(result)
